export const STYLE_WEIGHT=.3,COMBO_CAP=48,MAX_COMBO_MULT=5;export function comboMultiplier(e){return 1+(Number.isFinite(e)&&e>0?Math.min(e,48):0)/48*4}export function liveStyle({bonus:e=0,combo:t=0,anomalyMult:r=1}){return .3*(Number(e)||0)*comboMultiplier(t)*(Number(r)||1)}export function liveScore({height:e=0,bankStyle:t=0,bonus:r=0,combo:n=0,tierWeight:o=1,anomalyMult:u=1}){const c=(Number(e)||0)/5,i=(Number(t)||0)+liveStyle({bonus:r,combo:n,anomalyMult:u});return Math.round((c+i)*(Number(o)||1))}export function finalScoreAfterBank(e,t){return Math.max(Number(e)||0,Number(t)||0)}
